  insert into public.incidents (id, case_reference, journey_id, category, severity, incident_status, description, hotel_notified, tourist_reference, resolution, created_at, updated_at, resolved_at) values
    ('44444444-4444-4444-8444-000000000001', 'CPT-3107', '33333333-3333-4333-8333-000000000007', 'overcharging', 'medium', 'investigating', 'Driver asked for R650 cash on arrival in Sea Point — far above the estimate shown. Tourist paid R400 and left the vehicle.', false, 'Chloé D.', null, now() - interval '4200 seconds', now() - interval '3600 seconds', null),
    ('44444444-4444-4444-8444-000000000002', 'CPT-2984', null, 'driver_impersonation', 'critical', 'acknowledged', 'Person in the arrivals hall claimed to be a ride-hailing partner and asked the tourist to follow them to a private car. Tourist declined and reported it.', false, 'Anonymous visitor', null, now() - interval '5700 seconds', now() - interval '5100 seconds', null),
    ('44444444-4444-4444-8444-000000000003', 'CPT-2755', '33333333-3333-4333-8333-000000000008', 'unsafe_route', 'high', 'new', 'Simulated deviation alert: vehicle left the expected route towards Stellenbosch. Awaiting check-in with tourist.', false, 'James K.', null, now() - interval '120 seconds', now() - interval '120 seconds', null),
    ('44444444-4444-4444-8444-000000000004', 'CPT-2876', null, 'vehicle_mismatch', 'high', 'resolved', 'Registration plate did not match booking details. Tourist did not enter the vehicle and rebooked.', false, 'Anonymous visitor', 'Tourist rebooked with a verified driver. Unverified vehicle reported to operator.', now() - interval '93600 seconds', now() - interval '93000 seconds', now() - interval '90000 seconds'),
    ('44444444-4444-4444-8444-000000000005', 'CPT-2690', null, 'harassment', 'critical', 'closed', 'Tourist reported verbal harassment during the trip. Driver account suspended pending review.', false, 'Anonymous visitor', 'Driver CPT-DRV-007 suspended. Tourist offered follow-up support.', now() - interval '259200 seconds', now() - interval '258600 seconds', now() - interval '255600 seconds'),
    ('44444444-4444-4444-8444-000000000006', 'CPT-2611', null, 'lost_tourist', 'medium', 'resolved', 'Tourist could not find the pickup point after leaving arrivals.', false, 'Anonymous visitor', 'Guided to the designated pickup area via chat.', now() - interval '345600 seconds', now() - interval '345000 seconds', now() - interval '342000 seconds'),
    ('44444444-4444-4444-8444-000000000007', 'CPT-2540', null, 'theft', 'high', 'closed', 'Phone snatched through an open car window at a traffic light near the CBD.', false, 'Anonymous visitor', 'Tourist referred to SAPS to open a case. Safety tip added to insights.', now() - interval '518400 seconds', now() - interval '517800 seconds', now() - interval '514800 seconds'),
    ('44444444-4444-4444-8444-000000000008', 'CPT-2477', null, 'overcharging', 'low', 'resolved', 'Driver added an unexplained "airport fee" of R80.', false, 'Anonymous visitor', 'Fare difference refunded by operator after review.', now() - interval '777600 seconds', now() - interval '777000 seconds', now() - interval '774000 seconds'),
    ('44444444-4444-4444-8444-000000000009', 'CPT-2399', null, 'driver_not_found', 'medium', 'closed', 'Booked driver could not be located at arrivals for 25 minutes.', false, 'Anonymous visitor', 'Driver was waiting at the wrong terminal exit. Pickup instructions improved.', now() - interval '1036800 seconds', now() - interval '1036200 seconds', now() - interval '1033200 seconds');
