  insert into public.scam_reports (id, category, location, description, severity, verification_status, anonymous, created_at) values
    ('55555555-5555-4555-8555-000000000001', 'fake_ridehailing', 'CPT Airport — arrivals hall', 'Man approached at arrivals saying he was "the Uber driver" without naming me or showing the app booking.', 'high', 'pattern_confirmed', true, now() - interval '86400 seconds'),
    ('55555555-5555-4555-8555-000000000002', 'airport_overcharging', 'CPT Airport — pickup area', 'Unmarked car quoted R900 to the CBD.', 'medium', 'under_review', true, now() - interval '172800 seconds'),
    ('55555555-5555-4555-8555-000000000003', 'taxi_impersonation', 'CPT Airport — arrivals hall', 'Person with a lanyard claimed to be official airport transport and asked for cash upfront.', 'high', 'pattern_confirmed', true, now() - interval '345600 seconds'),
    ('55555555-5555-4555-8555-000000000004', 'atm_scam', 'Long Street, CBD', 'Stranger offered to "help" at the ATM and tried to see my PIN.', 'high', 'under_review', true, now() - interval '518400 seconds'),
    ('55555555-5555-4555-8555-000000000005', 'fake_guide', 'Table Mountain lower cableway', 'Unofficial guide sold "skip the queue" tickets that were not valid.', 'medium', 'unverified', true, now() - interval '691200 seconds'),
    ('55555555-5555-4555-8555-000000000006', 'distraction_theft', 'Greenmarket Square', 'Someone spilled a drink on me while another person reached for my bag.', 'medium', 'pattern_confirmed', true, now() - interval '864000 seconds'),
    ('55555555-5555-4555-8555-000000000007', 'fake_ridehailing', 'CPT Airport — pickup area', 'Driver called my name but the registration did not match the app.', 'high', 'pattern_confirmed', true, now() - interval '1036800 seconds'),
    ('55555555-5555-4555-8555-000000000008', 'accommodation_scam', 'Sea Point', 'Listing asked for a deposit by bank transfer outside the booking platform.', 'high', 'under_review', true, now() - interval '1296000 seconds'),
    ('55555555-5555-4555-8555-000000000009', 'card_fraud', 'V&A Waterfront', 'Card skimmed at a portable card machine at a market stall.', 'medium', 'unverified', true, now() - interval '1555200 seconds'),
    ('55555555-5555-4555-8555-000000000010', 'airport_overcharging', 'CPT Airport — arrivals hall', 'Driver refused to use the app and demanded a fixed cash price.', 'medium', 'pattern_confirmed', true, now() - interval '1814400 seconds'),
    ('55555555-5555-4555-8555-000000000011', 'fake_tour_operator', 'Bo-Kaap', 'Paid a deposit online for a tour that never showed up.', 'medium', 'under_review', true, now() - interval '2160000 seconds'),
    ('55555555-5555-4555-8555-000000000012', 'distraction_theft', 'Camps Bay', 'Phone taken from the table while someone asked for directions.', 'low', 'unverified', true, now() - interval '2592000 seconds'),
    ('55555555-5555-4555-8555-000000000013', 'taxi_impersonation', 'Cape Town Station', 'Unmarked car with a removable "taxi" sign charged triple the meter rate.', 'medium', 'unverified', true, now() - interval '3110400 seconds'),
    ('55555555-5555-4555-8555-000000000014', 'fake_ridehailing', 'V&A Waterfront', 'Car pulled up claiming to be my ride before the app showed the driver had arrived.', 'high', 'under_review', true, now() - interval '3628800 seconds'),
    ('55555555-5555-4555-8555-000000000015', 'atm_scam', 'Century City', 'Card got "stuck"; a bystander offered help and asked me to re-enter the PIN.', 'high', 'pattern_confirmed', true, now() - interval '4320000 seconds');
